"""R13: ángulos y primeras construcciones, con diagramas explícitos."""
import json
from pathlib import Path
U=[]
def v(angle=60,**kw):return dict(tipo='angulo',angulo=angle,**kw)
def a(q,value,steps,wrong,visual):
 opts=list(dict.fromkeys([str(value),*map(str,wrong)]));assert len(opts)>1
 return dict(enunciado=q,respuesta_correcta=str(value),opciones=opts,paso_resuelto=steps,visual=visual)
def unit(id,anchor,title,exp,example,steps,hint,rows,visual,before=False):
 for i,r in enumerate(rows):
  r['id']=id+'-v'+str(i+1);k=i%len(r['opciones']);r['opciones']=r['opciones'][k:]+r['opciones'][:k]
 assert len(rows)==6
 U.append(dict(id=id,tema='geometria_angulos',**({'antes_de':anchor} if before else {'despues_de':anchor}),titulo=title,explicacion=exp,ejemplo=example,pasos=steps,pista=hint,actividades=rows,visual=visual))
unit('prof_geo_elementos','mat_ang_clases','Dos lados que nacen del mismo punto','Un ángulo tiene dos lados que son semirrectas y nacen en un punto común, el vértice. Medimos la abertura entre los lados, no su longitud. Al escribir AOB, la letra del medio, O, nombra el vértice.','En el dibujo, OA y OB son los lados y O es el vértice.',['Buscamos dónde se encuentran los dos lados.','Ese punto común es O: es el vértice.'],'Buscá el punto del que salen ambos lados.',[a('Mirá el dibujo. ¿Qué letra nombra el vértice?',o,f'Los dos lados salen de {o}. Ese punto común es el vértice.',[x,y],v(n,letras=[o,x,y])) for o,x,y,n in [('O','A','B',60),('P','C','D',80),('Q','E','F',40),('R','G','H',120),('S','J','K',100),('T','L','M',30)]],v(60,letras=['O','A','B']),True)
unit('prof_geo_transportador','mat_ang_clases','Empezar por el cero correcto','Ponemos el centro del transportador en el vértice y alineamos un lado con el cero. Leemos la escala que comienza en ese cero hasta el otro lado. Si el lado inicial apunta a la izquierda, usamos el cero de la izquierda.','El lado naranja llega a 60° si empezamos en el cero derecho.',['El centro coincide con O y el lado azul pasa por el cero derecho.','Seguimos esa escala hasta el lado naranja: 60°.'],'Elegí primero el cero sobre el lado azul.',[a('Medí la abertura marcada. ¿Cuántos grados hay desde el lado azul hasta el naranja?',n,f'Empezamos en el cero de la {"izquierda" if left else "derecha"}.\nSeguimos esa escala hasta el lado naranja: {n}°.',[180-n,n+10],v(n,transportador=True,izquierda=left)) for n,left in [(60,False),(40,True),(120,False),(70,True),(130,True),(30,False)]],v(60,transportador=True))
unit('prof_geo_trazado','prof_geo_transportador','Construir un ángulo con transportador','Para dibujar un ángulo, trazamos un lado y marcamos el vértice. Apoyamos allí el centro del transportador, alineamos el cero con el lado y marcamos la medida pedida. Al unir el vértice con esa marca obtenemos el segundo lado.','Para dibujar 60°, marcamos 60 en la escala que empieza en el lado azul.',['En la app, explorá la abertura con el control. En papel, dibujá el primer lado y ubicá el centro y el cero.','Marcá 60° y trazá desde el vértice una semirrecta que pase por la marca.'],'La marca indica por dónde debe pasar el segundo lado.',[a(f'Queremos construir un ángulo de {n}°. ¿En qué número de la escala que empieza en el lado azul marcamos el punto?',n,f'El centro va en el vértice. Usamos el cero del lado azul y marcamos {n}°.\nUnimos el vértice con esa marca para trazar el segundo lado.',[180-n,n+10],v(n,transportador=True)) for n in [60,40,120,70,130,30]],v(60,transportador=True,interactivo=True))
unit('prof_geo_perpendiculares','prof_geo_trazado','Rectas que forman cuatro ángulos rectos','Dos rectas perpendiculares se cortan formando cuatro ángulos de 90°. Una escuadra permite comprobar el ángulo recto. Que dos rectas se crucen no alcanza para que sean perpendiculares.','Las rectas del dibujo forman cuatro ángulos de 90°.',['Apoyamos los dos lados del ángulo recto de la escuadra sobre las rectas.','Si coinciden, las rectas son perpendiculares. Cada abertura mide 90°.'],'Buscá ángulos rectos, no solo un cruce.',[a(f'Dos rectas se cortan y uno de sus ángulos mide {n}°. ¿Son perpendiculares?','Sí' if n==90 else 'No',f'{n}° '+('es un ángulo recto: las rectas son perpendiculares.' if n==90 else 'no es 90°: estas rectas no son perpendiculares.'),['Sí','No'],v(n,rectas=True,medida=True)) for n in [90,60,120,90,40,90]],v(90,rectas=True,medida=True))
unit('prof_geo_opuestos','mat_ang_complemento','Ángulos enfrentados en un cruce','Cuando dos rectas se cruzan, los ángulos opuestos por el vértice están enfrentados y miden lo mismo. Los que quedan uno al lado del otro sobre una recta suman 180°. Miramos qué ángulo pide la pregunta antes de calcular.','Si el ángulo naranja mide 60°, el que está enfrente también mide 60°.',['Ubicamos el ángulo enfrentado: sus lados prolongan los del ángulo naranja.','Los opuestos por el vértice son iguales: el ángulo pedido mide 60°.'],'El opuesto está enfrente; el adyacente queda al lado.',[a(f'El ángulo naranja mide {n}°. ¿Cuánto mide el ángulo verde enfrentado?',n,f'Son opuestos por el vértice, por eso tienen la misma medida.\nEl verde mide {n}°.',[180-n,n+10],v(n,rectas=True,opuesto=True,medida=True)) for n in [60,40,120,70,130,30]],v(60,rectas=True,opuesto=True,medida=True))
unit('prof_geo_bisectriz','prof_geo_opuestos','Partir una abertura en dos iguales','La bisectriz es una semirrecta que sale del vértice y divide el ángulo en dos ángulos iguales. Cada parte mide la mitad del ángulo original. No alcanza con dibujar una línea cualquiera dentro del ángulo.','La bisectriz de un ángulo de 80° forma dos ángulos de 40°.',['Dividimos la medida total por dos: 80 ÷ 2 = 40°.','Comprobamos: 40° + 40° = 80°.'],'La bisectriz reparte la medida en dos partes iguales.',[a(f'La línea verde es la bisectriz de un ángulo de {n}°. ¿Cuántos grados mide cada mitad?',n//2,f'{n} ÷ 2 = {n//2}°.\nComprobamos: {n//2}° + {n//2}° = {n}°.',[n,180-n],v(n,bisectriz=True,medida=True)) for n in [80,60,100,120,140,40]],v(80,bisectriz=True,medida=True))
unit('prof_geo_compas','prof_geo_bisectriz','Trazar la bisectriz con regla y compás','Con centro en O trazamos un arco que corte los lados en A y B. Desde A y B hacemos dos arcos con la misma apertura, suficientemente grande para que se crucen dentro del ángulo en P. La semirrecta OP es la bisectriz.','Los arcos con centro en A y B usan la misma apertura del compás.',['En papel, trazá el arco desde O. Desde A y B, sin cambiar la apertura entre esos dos arcos, marcá el cruce interior P.','Con regla, trazá la semirrecta que sale de O y pasa por P. Comprobá las dos mitades con el transportador.'],'Conservá la misma apertura para los arcos con centro en A y B.',[a(q,correct,solution,wrong,v(60,compas=True,bisectriz=True)) for q,correct,solution,wrong in [('¿Qué debe mantenerse igual al trazar los arcos desde A y B?','La apertura del compás','Los arcos desde A y B tienen el mismo radio.',['La longitud de la regla','El nombre del vértice']),('¿Dónde apoyamos primero la punta del compás para marcar A y B?','En O','El primer arco se traza con centro en el vértice O.',['En P','Fuera del ángulo']),('Ya marcamos el cruce interior P. ¿Qué semirrecta trazamos?','OP','Unimos el vértice O con el cruce P y prolongamos desde O.',['AB','AP']),('Si los arcos desde A y B no se cruzan, ¿cómo seguimos?','Aumentamos la apertura por igual en ambos','Rehacemos ambos arcos con un mismo radio mayor hasta que se crucen.',['Cambiamos solo el arco de A','Elegimos cualquier punto']),('¿Para qué marcamos A y B con el mismo arco desde O?','Para que OA y OB midan lo mismo','A y B están sobre un mismo arco con centro en O: OA y OB son radios iguales.',['Para que el ángulo mida 90°','Para alargar un solo lado']),('Al comprobar el trazado, ¿cómo deben ser las dos mitades?','De igual medida','La bisectriz divide el ángulo en dos ángulos iguales.',['Una mayor que la otra','Siempre de 90°'])]],v(60,compas=True,bisectriz=True))
unit('prof_geo_mediatriz','prof_geo_compas','Encontrar la mitad y trazar una perpendicular','La mediatriz es la recta perpendicular a un segmento que pasa por su punto medio. Para construirla, trazamos arcos desde A y B con el mismo radio, mayor que la mitad del segmento. Unimos sus dos cruces C y D: la recta resultante corta AB en su mitad M.','Si AB mide 8 cm, M deja 4 cm a cada lado y la mediatriz forma 90° con AB.',['En papel, dibujá AB. Sin cambiar la apertura entre A y B, trazá arcos que se crucen arriba y abajo.','Uní C con D usando la regla. Comprobá que AM = MB y que el cruce forma un ángulo recto.'],'La mediatriz cumple dos condiciones: punto medio y perpendicularidad.',[a(f'AB mide {n} cm y la recta verde es su mediatriz. ¿Cuántos centímetros mide AM?',n//2,f'M es el punto medio: {n} ÷ 2 = {n//2} cm.\nAM = MB = {n//2} cm y la recta CD es perpendicular a AB.',[n,n//2+1],dict(tipo='mediatriz',longitud=n)) for n in [8,6,10,12,14,16]],dict(tipo='mediatriz',longitud=8))
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8');start='// R13: geometria con diagramas.';end='// FIN R13'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst GEOMETRIA_R13 = '+json.dumps(U,ensure_ascii=False,indent=2)+''';
for (const unidad of GEOMETRIA_R13) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === (unidad.antes_de || unidad.despues_de));
 if (indice < 0) throw new Error('Falta el paso de referencia de ' + unidad.id);
 UNIDADES_BASES.splice(indice + (unidad.antes_de ? 0 : 1), 0, unidad);
}
'''+end+'\n\n';i=min(s.index(m) for m in ['// R14: figuras y superficies.','// R15: problemas por etapas.','// R16: lectura con evidencia.','export const TEMAS_BASES'] if m in s);p.write_text(s[:i]+code+s[i:],encoding='utf-8');print(len(U),'unidades;',len(U)*6,'actividades')
